  getUser: async (id) => { order.push("user"); return { id, name: "Ada" }; },
  getSettings: async (uid) => { order.push("settings"); return { theme: uid === 7 ? "dark" : "x" }; },
  getFriends: async (uid) => { order.push("friends"); return ["Grace"]; },
};
const out = await fetchProfile(db);
